/* aesthetic board v2.17.1 — generated by scripts/build-registry.mjs. */
@import './aesthetic.base.css';

:root {
  --ae-ink-muted: #737373;
  --ae-line: #e9e9e9;
  --ae-ink-muted-dark: #8f8f8f;
  --ae-line-dark: #262626;
  --ae-w-medium: 550;
  --ae-space-3: 0.75em;
  --ae-space-4: 1em;
  --ae-space-6: 2em;
}

@media (prefers-color-scheme: dark) {
  :root:not(.light):not([data-ae-mode='light']) {
    --ae-ink-muted: var(--ae-ink-muted-dark);
    --ae-line: var(--ae-line-dark);
  }
}

.light,
[data-ae-mode='light'] {
  color-scheme: light;
}

:root.dark,
:root[data-ae-mode='dark'] {
  color-scheme: dark;
  --ae-ink-muted: var(--ae-ink-muted-dark);
  --ae-line: var(--ae-line-dark);
}

.ae-item {
font-weight: var(--ae-w-medium);
}

.ae-dim {
color: var(--ae-ink-muted);
}

.ae-board {
display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 18rem), 1fr));
  gap: var(--ae-space-6);
  align-items: start;
}

.ae-column {
min-width: 0;
  border-top: 1px solid var(--ae-line);
  padding-top: var(--ae-space-4);
}

.ae-column-head {
display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: var(--ae-space-4);
  margin-bottom: var(--ae-space-4);
}

.ae-column-title {
font-weight: var(--ae-w-medium);
}

.ae-column-meta {
font-family: var(--ae-font-mono);
  font-size: 13px;
  color: var(--ae-ink-muted);
  white-space: nowrap;
}

.ae-column-body {
display: grid;
  gap: var(--ae-space-3);
}

.ae-board-card {
border-top: 1px solid var(--ae-line);
  padding-top: var(--ae-space-3);
}

.ae-board-card:first-child {
border-top: 0;
  padding-top: 0;
}

@media (max-width: 48rem) {
  .ae-board {
  grid-template-columns: 1fr;
  }
}
